return $input.all().map(i => {
  const r = i.json;
  const title = r.title || '';
  const p = title.split(':');
  return {json:{
    empresa: p.length > 1 ? p[0].trim() : (r.creator || 'Não informado'),
    cargo: p.length > 1 ? p.slice(1).join(':').trim() : title,
    descricao: r.contentSnippet || r.content || r.description || '',
    link: r.link || '',
    localizacao: 'Remoto',
    tipo: 'Remoto',
    fonte: 'RSS - We Work Remotely'
  }};
}).filter(i => i.json.cargo && i.json.link);

function hashString(str) {
  let hash1 = 0xdeadbeef;
  let hash2 = 0x41c6ce57;

  for (let i = 0; i < str.length; i++) {
    const ch = str.charCodeAt(i);

    hash1 = Math.imul(hash1 ^ ch, 2654435761);
    hash2 = Math.imul(hash2 ^ ch, 1597334677);
  }

  hash1 =
    Math.imul(hash1 ^ (hash1 >>> 16), 2246822507) ^
    Math.imul(hash2 ^ (hash2 >>> 13), 3266489909);

  hash2 =
    Math.imul(hash2 ^ (hash2 >>> 16), 2246822507) ^
    Math.imul(hash1 ^ (hash1 >>> 13), 3266489909);

  return (
    (hash2 >>> 0).toString(16).padStart(8, '0') +
    (hash1 >>> 0).toString(16).padStart(8, '0')
  );
}

const seen = new Set();
const output = [];

for (const item of $input.all()) {
  const j = item.json;

  const canonicalUrl = String(j.link || '')
    .trim()
    .toLowerCase()
    .replace(/[?#].*$/, '')
    .replace(/\/$/, '');

  const fallbackKey = [
    j.company || '',
    j.title || '',
    j.location || ''
  ]
    .join('|')
    .toLowerCase()
    .trim();

  const baseKey = canonicalUrl || fallbackKey;

  if (!baseKey) {
    continue;
  }

  const id = hashString(baseKey);

  // Remove duplicatas dentro do lote atual
  if (seen.has(id)) {
    continue;
  }

  seen.add(id);

  output.push({
    json: {
      ...j,
      id,
      data_encontrada: new Date().toISOString()
    }
  });
}

return output;

const job = $('Rate Limit - 2s').item.json;

let raw =
  $json.text ??
  $json.output ??
  $json.response ??
  $json;

let result;

// Se o modelo já retornar objeto
if (typeof raw === 'object' && raw !== null) {
  result = raw;
} else {
  let text = String(raw || '').trim();

  text = text
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```\s*$/i, '')
    .trim();

  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');

  if (start === -1 || end === -1 || end < start) {
    throw new Error(
      'Resposta do Recruiter não contém JSON completo: ' +
      text.slice(0, 1500)
    );
  }

  const jsonText = text.slice(start, end + 1);

  try {
    result = JSON.parse(jsonText);
  } catch (error) {
    throw new Error(
      'JSON inválido retornado pelo Recruiter: ' +
      error.message +
      ' | Conteúdo: ' +
      jsonText.slice(0, 1500)
    );
  }
}

// Score
let score = Number(result.score ?? 0);

if (!Number.isFinite(score)) {
  score = 0;
}

score = Math.max(
  0,
  Math.min(100, Math.round(score))
);

// Motivos
const motivos = Array.isArray(result.motivos)
  ? result.motivos
      .map(String)
      .map(x => x.trim())
      .filter(Boolean)
      .slice(0, 4)
  : [];

// Lacunas
const lacunas = Array.isArray(result.lacunas)
  ? result.lacunas
      .map(String)
      .map(x => x.trim())
      .filter(Boolean)
      .slice(0, 4)
  : [];

return [
  {
    json: {
      ...job,

      score,
      motivos,
      lacunas,

      // A regra fica determinística no n8n,
      // independentemente do boolean retornado pelo LLM.
      recomendado: score >= 70
    }
  }
];

