const q = $json.callback_query;

if (!q?.data) {
  throw new Error('Callback sem data');
}

const [action, id] = q.data.split(':');

const allowedActions = [
  'approve',
  'reject',
  'retry'
];

if (!allowedActions.includes(action) || !id) {
  throw new Error(
    'Callback inválido: ' + q.data
  );
}

return [{
  json: {
    action,
    id,
    queryId: q.id,
    chatId: String(q.message?.chat?.id || ''),
    userId: String(q.from?.id || ''),
    messageId: q.message?.message_id
  }
}];

const cb = $('Parse Telegram Callback').item.json;
if (!$json.ID) throw new Error('Vaga não encontrada no Sheets: '+cb.id);
return [{json:{...$json,_action:cb.action,_queryId:cb.queryId,_chatId:cb.chatId,_messageId:cb.messageId}}];

