const existingRows = $input.all();

const existingIds = new Set(
  existingRows
    .map(item => String(item.json.ID || '').trim())
    .filter(Boolean)
);

const incomingJobs = $('Build Deterministic Job ID').all();

const newJobs = incomingJobs.filter(item => {
  const id = String(item.json.id || '').trim();

  return id && !existingIds.has(id);
});

return newJobs;

const html = $input.first().json.data || '';

if (!html) {
  throw new Error('Scout - ProgramaThor não retornou HTML no campo data.');
}

function decodeHtml(text = '') {
  return String(text)
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&nbsp;/g, ' ')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&ndash;/g, '–')
    .replace(/&mdash;/g, '—')
    .replace(/&rsquo;/g, '’')
    .replace(/&#(\d+);/g, (_, code) =>
      String.fromCharCode(Number(code))
    );
}

function cleanText(text = '') {
  return decodeHtml(
    String(text)
      .replace(/<script[\s\S]*?<\/script>/gi, '')
      .replace(/<style[\s\S]*?<\/style>/gi, '')
      .replace(/<[^>]+>/g, ' ')
  )
    .replace(/\s+/g, ' ')
    .trim();
}

const jobs = [];

// Captura somente links de vagas individuais
const jobRegex =
  /<a\s+href="(\/jobs\/\d+[^"]*)"[^>]*>([\s\S]*?)<\/a>/gi;

let match;

while ((match = jobRegex.exec(html)) !== null) {
  const relativeLink = match[1];
  const block = match[2];

  // Cargo
  const titleMatch = block.match(
    /<h3[^>]*>([\s\S]*?)<\/h3>/i
  );

  if (!titleMatch) {
    continue;
  }

  const title = cleanText(titleMatch[1])
    .replace(/\bNOVA\b/gi, '')
    .trim();

  // Metadados da vaga
  const infoMatch = block.match(
    /<div class=['"]cell-list-content-icon['"]>([\s\S]*?)<\/div>/i
  );

  const infos = [];

  if (infoMatch) {
    const spanRegex = /<span[^>]*>([\s\S]*?)<\/span>/gi;

    let span;

    while ((span = spanRegex.exec(infoMatch[1])) !== null) {
      const value = cleanText(span[1]);

      if (value) {
        infos.push(value);
      }
    }
  }

  const company = infos[0] || '';
  const location = infos[1] || '';

  let companySize = '';
  let salary = '';
  let seniority = '';
  let contract = '';

  for (const value of infos.slice(2)) {
    if (
      /startup|grande empresa|pequena\/média empresa/i.test(value)
    ) {
      companySize = value;
      continue;
    }

    if (/R\$|USD|salário|acima de|até/i.test(value)) {
      salary = value;
      continue;
    }

    if (/júnior|junior|pleno|sênior|senior|estágio|estagio/i.test(value)) {
      seniority = value;
      continue;
    }

    if (/\bCLT\b|\bPJ\b|estágio|estagio/i.test(value)) {
      contract = value;
    }
  }

  // Tecnologias / skills
  const technologies = [];

  const tagRegex =
    /<span[^>]*class=['"][^'"]*tag-list[^'"]*background-gray[^'"]*['"][^>]*>([\s\S]*?)<\/span>/gi;

  let tag;

  while ((tag = tagRegex.exec(block)) !== null) {
    const value = cleanText(tag[1]);

    if (value && !technologies.includes(value)) {
      technologies.push(value);
    }
  }

  const external =
    /VAGA EXTERNA/i.test(block);

  const link =
    `https://programathor.com.br${relativeLink}`;

  const description = [
    `Cargo: ${title}`,
    company ? `Empresa: ${company}` : '',
    location ? `Local: ${location}` : '',
    seniority ? `Senioridade: ${seniority}` : '',
    contract ? `Contrato: ${contract}` : '',
    salary ? `Salário: ${salary}` : '',
    technologies.length
      ? `Tecnologias: ${technologies.join(', ')}`
      : '',
    external
      ? 'Vaga externa com redirecionamento para candidatura.'
      : ''
  ]
    .filter(Boolean)
    .join('\n');

  jobs.push({
    json: {
      source: 'ProgramaThor',

      title,
      company,
      location,

      work_mode:
        /remoto/i.test(location)
          ? 'Remoto'
          : location,

      company_size: companySize,
      seniority,
      contract,
      salary,

      technologies,

      link,

      description,

      external,

      published_at: null
    }
  });
}

if (!jobs.length) {
  throw new Error(
    'Nenhuma vaga foi encontrada no HTML do ProgramaThor.'
  );
}

return jobs;

const items = $input.all();

function cleanText(value = '') {
  return String(value)
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

const output = [];

for (const item of items) {
  const json = item.json || {};

  // Ignora item vazio gerado pelo n8n
  if (!Object.keys(json).length) {
    continue;
  }

  const title =
    cleanText(
      json.title ??
      json.name ??
      json.headline ??
      ''
    );

  let link =
    json.link ??
    json.url ??
    json.guid ??
    '';

  // Alguns parsers de Atom podem devolver link como objeto
  if (link && typeof link === 'object') {
    link =
      link.href ??
      link.url ??
      '';
  }

  // Ou como array
  if (Array.isArray(link)) {
    const firstValid = link.find(x => {
      if (typeof x === 'string') return true;
      return x?.href || x?.url;
    });

    if (typeof firstValid === 'string') {
      link = firstValid;
    } else if (firstValid) {
      link =
        firstValid.href ??
        firstValid.url ??
        '';
    }
  }

  link = String(link || '').trim();

  const rawContent =
    json.content ??
    json.contentSnippet ??
    json.summary ??
    json.description ??
    json.snippet ??
    '';

  const description = cleanText(rawContent);

  const publishedAt =
    json.isoDate ??
    json.pubDate ??
    json.published ??
    json.updated ??
    null;

  // Se não temos nem título nem link, não vale processar
  if (!title && !link) {
    continue;
  }

  output.push({
    json: {
      source: 'Google Alerts',
      title,
      company: '',
      location: '',
      work_mode: '',
      company_size: '',
      seniority: '',
      contract: '',
      salary: '',
      technologies: [],
      link,
      description,
      external: true,
      published_at: publishedAt
    }
  });
}

return output;

const items = $input.all();

const output = [];

for (const item of items) {
  const j = item.json || {};

  const source = String(
    j.source ??
    j.fonte ??
    'Desconhecida'
  ).trim();

  const title = String(
    j.title ??
    j.cargo ??
    ''
  ).trim();

  const company = String(
    j.company ??
    j.empresa ??
    ''
  ).trim();

  const location = String(
    j.location ??
    j.localizacao ??
    ''
  ).trim();

  const workMode = String(
    j.work_mode ??
    j.tipo ??
    ''
  ).trim();

  const link = String(
    j.link ??
    j.url ??
    ''
  ).trim();

  const description = String(
    j.description ??
    j.descricao ??
    ''
  ).trim();

  const technologies = Array.isArray(j.technologies)
    ? j.technologies
    : [];

  const seniority = String(
    j.seniority ?? ''
  ).trim();

  const contract = String(
    j.contract ?? ''
  ).trim();

  const salary = String(
    j.salary ?? ''
  ).trim();

  const companySize = String(
    j.company_size ?? ''
  ).trim();

  const external = Boolean(
    j.external ?? false
  );

  const publishedAt =
    j.published_at ??
    j.isoDate ??
    j.pubDate ??
    null;

  // Não deixa passar registros que não parecem vagas
  if (!title && !link) {
    continue;
  }

  output.push({
    json: {
      source,
      title,
      company,
      location,
      work_mode: workMode,

      seniority,
      contract,
      salary,
      company_size: companySize,

      technologies,

      link,
      description,

      external,
      published_at: publishedAt
    }
  });
}

return output;
